const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const N = data[idx++];

const dice = [];
for (let i = 0; i < N; i++) {
    const A = data[idx++], B = data[idx++], C = data[idx++];
    const D = data[idx++], E = data[idx++], F = data[idx++];

    const opp = new Array(7).fill(0);
    opp[A] = F;
    opp[F] = A;
    opp[B] = D;
    opp[D] = B;
    opp[C] = E;
    opp[E] = C;

    const contrib = new Array(7).fill(0);
    for (let b = 1; b <= 6; b++) {
        const top = opp[b];
        let maxSide = 0;
        for (let v = 1; v <= 6; v++) {
            if (v !== b && v !== top && v > maxSide) {
                maxSide = v;
            }
        }
        contrib[b] = maxSide;
    }

    dice.push({ opp, contrib });
}

let dp = new Array(7).fill(-Infinity);

const first = dice[0];
for (let b = 1; b <= 6; b++) {
    const top = first.opp[b];
    dp[top] = Math.max(dp[top], first.contrib[b]);
}

for (let i = 1; i < N; i++) {
    const die = dice[i];
    const ndp = new Array(7).fill(-Infinity);

    for (let v = 1; v <= 6; v++) {
        if (dp[v] !== -Infinity) {
            const b = v;
            const top = die.opp[b];
            ndp[top] = Math.max(ndp[top], dp[v] + die.contrib[b]);
        }
    }

    dp = ndp;
}

let ans = 0;
for (let v = 1; v <= 6; v++) {
    if (dp[v] > ans) ans = dp[v];
}

console.log(ans);
